<div class="d-flex justify-content-between align-items-end gap-3 flex-wrap"><div class="page-heading mb-0"><span class="section-kicker">Panel pelayanan</span><h1>Ringkasan layanan</h1><p>Ikhtisar pengajuan surat Desa Sukakerta.</p></div><span class="small text-secondary"><?= e(date('l, d F Y')) ?></span></div><div class="metric-grid"><div class="metric"><span>Total pengajuan</span><strong><?= (int) $stats['total'] ?></strong></div><div class="metric"><span>Menunggu pemeriksaan</span><strong><?= (int) $stats['baru'] ?></strong></div><div class="metric"><span>Sedang diproses</span><strong><?= (int) $stats['proses'] ?></strong></div><div class="metric"><span>Surat diterbitkan</span><strong><?= (int) $stats['terbit'] ?></strong></div></div><section class="data-panel"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">Aktivitas pengajuan terbaru</h2><a class="small" href="/admin/pengajuan">Semua pengajuan</a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Warga</th><th>Jenis surat</th><th>Status</th><th>Diterima</th><th></th></tr></thead><tbody><?php foreach ($recent as $item): ?><tr><td><?= e($item['full_name']) ?></td><td><?= e($item['type_name']) ?></td><td><span class="status-pill pending"><?= e(status_label($item['status'])) ?></span></td><td><?= e(date('d/m/Y', strtotime($item['created_at']))) ?></td><td><a href="/admin/pengajuan/<?= (int) $item['id'] ?>">Tinjau</a></td></tr><?php endforeach; ?><?php if (!$recent): ?><tr><td colspan="5" class="text-center text-secondary py-4">Belum ada pengajuan.</td></tr><?php endif; ?></tbody></table></div></section>